function NEWTON_ONE_ROW(N):
    q[0] <- 1
    for m from 0 to N-1:
        acc <- 0
        for k from 0 to floor(m/2):
            acc <- acc + 2 * p_{2k+1} * q[m - 2k]
        q[m+1] <- (1/(m+1)) * acc
    return q[0..N]

