from typing import Callable, Dict, List, Tuple
from fractions import Fraction

Monomial = Tuple[Tuple[int, int], ...]
Poly = Dict[Monomial, Fraction]


def newton_one_row(num_rows: int) -> List[Poly]:
    """Compute q_0, ..., q_{num_rows} via the Schur-Q Newton recursion.

    q_0 = 1;  q_{m+1} = (1/(m+1)) * sum_{k=0}^{floor(m/2)} 2 * p_{2k+1} * q_{m-2k}.
    Coefficients are exact rationals; monomials are products of odd power sums
    p_{2k+1} encoded by the variable index k.
    """
    def mon_mul(a: Monomial, b: Monomial) -> Monomial:
        e: Dict[int, int] = {}
        for i, x in a:
            e[i] = e.get(i, 0) + x
        for i, x in b:
            e[i] = e.get(i, 0) + x
        return tuple(sorted((i, x) for i, x in e.items() if x))

    def scale(c: Fraction, poly: Poly) -> Poly:
        return {m: c * v for m, v in poly.items()}

    def add(a: Poly, b: Poly) -> Poly:
        out = dict(a)
        for m, v in b.items():
            nv = out.get(m, Fraction(0)) + v
            if nv == 0:
                out.pop(m, None)
            else:
                out[m] = nv
        return out

    qs: List[Poly] = [{(): Fraction(1)}]
    for mp1 in range(1, num_rows + 1):
        m = mp1 - 1
        acc: Poly = {}
        for k in range(m // 2 + 1):
            pk: Poly = {(((k, 1),)): Fraction(2)}
            term = {mon_mul(mm, ((k, 1),)): Fraction(2) * v
                    for mm, v in qs[m - 2 * k].items()}
            acc = add(acc, term)
        qs.append(scale(Fraction(1, mp1), acc))
    return qs

from typing import Dict, Tuple
from fractions import Fraction

Monomial = Tuple[Tuple[int, int], ...]
# A t-coefficient is a dict {power_of_t: rational}.
TCoeff = Dict[int, Fraction]
TPoly = Dict[Monomial, TCoeff]


def apply_phi_t(qpoly: Dict[Monomial, Fraction]) -> TPoly:
    """Apply the plethysm phi_t: p_{2k+1} -> (1 - t^{2k+1}) p_{2k+1}.

    For each monomial prod_k p_{2k+1}^{e_k} with rational coefficient c, multiply
    c by prod_k (1 - t^{2k+1})^{e_k}, producing a coefficient that is a polynomial
    in t (stored as {t-power: rational}). The monomial itself is unchanged. This
    realizes S^t_lambda = phi_t(Q_lambda) given Q_lambda in odd power sums.
    """
    def tmul(a: TCoeff, b: TCoeff) -> TCoeff:
        out: TCoeff = {}
        for da, va in a.items():
            for db, vb in b.items():
                out[da + db] = out.get(da + db, Fraction(0)) + va * vb
        return {d: v for d, v in out.items() if v != 0}

    def one_minus_tpow(n: int) -> TCoeff:
        return {0: Fraction(1), n: Fraction(-1)}

    result: TPoly = {}
    for mon, c in qpoly.items():
        factor: TCoeff = {0: c}
        for idx, e in mon:
            for _ in range(e):
                factor = tmul(factor, one_minus_tpow(2 * idx + 1))
        result[mon] = factor
    return result

