        out = poly_add(out, {mon: sp.cancel(coeff * factor)})
    return out


def poly_eq(a: Poly, b: Poly) -> bool:
    """Decide equality of two polynomials over Q(t)."""
    diff = poly_add(a, poly_scale(sp.Integer(-1), b))
    return len(diff) == 0


def pretty(a: Poly) -> str:
    """Render a polynomial in readable p_{2k+1} notation."""
    if not a:
        return "0"
    parts = []
    for mon in sorted(a.keys(), key=lambda m: (sum(e for _, e in m), m)):
        coeff = a[mon]
        if not mon:
            parts.append(f"({sp.simplify(coeff)})")
            continue
        factors = "*".join(
            f"p{2 * idx + 1}" + (f"^{e}" if e != 1 else "") for idx, e in mon
        )
        parts.append(f"({sp.simplify(coeff)})*{factors}")
    return " + ".join(parts)


def main() -> None:
    print("=" * 72)
    print("Plethystic triviality of the shifted t-Schur basis")
    print("=" * 72)
    print()
    print("One-row Schur Q-functions q_n (in odd power sums p1=X0, p3=X1, ...):")
    for n in range(6):
        print(f"  q_{n} = {pretty(q(n))}")
    print()

    print("Verifying the creation-part intertwining  qt_n = phi_t(q_n):")
    all_ok = True
    for n in range(9):
        lhs = qt(n)
        rhs = phi_t(q(n))
        ok = poly_eq(lhs, rhs)
        all_ok = all_ok and ok
        print(f"  n={n}:  qt_n == phi_t(q_n)  ->  {ok}")
    print()
    print(f"All checked rows agree: {all_ok}")
    print()

    print("Illustration for n=3 (note the (1 - t^k) factors appearing):")
    print(f"  q_3        = {pretty(q(3))}")
    print(f"  qt_3       = {pretty(qt(3))}")
    print(f"  phi_t(q_3) = {pretty(phi_t(q(3)))}")
    print()
    print("Here q_3 = (4/3)*p1^3 + (2/3)*p3, and applying phi_t scales p1^3 by")
    print("(1 - t)^3 and p3 by (1 - t^3), exactly matching qt_3.")


if __name__ == "__main__":
    main()
